window.kbPageData["views/entry/k-71c30efc16f31b66"] = {"key":"entry/k-71c30efc16f31b66","state":{"route":"entry/k-71c30efc16f31b66"},"node":{"id":"k-71c30efc16f31b66","mode":"k","title":"两期比重与年均增长率","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["同一跨度内部分年均增速低于整体时，部分占整体的比重下降"],"qs":["江苏 2023 A类 行测#117"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"在统计口径可比、起止年份相同且部分与整体的基期值均为正时，部分的年均增长率低于整体，部分占整体的比重就下降。部分增长更快则比重上升，两者增速相同则比重不变。","review":{"definition":"在统计口径可比、起止年份相同且部分与整体的基期值均为正时，部分的年均增长率低于整体，部分占整体的比重就下降。部分增长更快则比重上升，两者增速相同则比重不变。","explanation":"期末比重等于基期比重乘以部分与整体累计增长倍数之比。两者跨越相同年数时，年均增速越高，累计增长倍数越大。本题按材料给出的增速比较2012年至2021年的变化，制造业增加值年均增长6.4%，低于国内生产总值的6.6%。其余三项的年均增速分别为9.2%、7.4%和11.6%，均高于6.6%，所以选A。","references":[],"evidence":"制造业增加值年均增长6.4%","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#117":{"paper":"江苏 2023 A类 行测","n":117,"mod":"资料分析","src":["22304fe4c340e19d7902.pdf",25],"asrc":["be17f9afe070cf13a0fb.pdf",37],"card":"d968961c4c0f091911389abc","links":[{"id":"k-71c30efc16f31b66","role":"解题依据","why":"跨度相同时，年均增速与累计增速的排序一致，可用部分与整体的年均增速判断比重变化方向。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-71c30efc16f31b66":[["江苏 2023 A类 行测#117"]]}};
